/// <summary>
/// AVA_008345_AssetAssuranceValue
/// </summary>
/// <returns>AssetInsuredValue</returns>
AssetInsuredValue AVAcalcInsuredValue()
{
    KCS_FABAssetInsIndexTable  insIndexTable;
    KCS_FABAssetInsIndexTable  insIndexTableActual;                                   

    if (this.KCS_FABAssetManualInsValue)
    {
        return this.InsuredValue;
    }

    if (!this.InsuranceDate1 || !this.KCS_FABAcquisitionPrice)
    {
        warning(strfmt("@FAB106",this.AssetId));
        return this.InsuredValue;
    }

    insIndexTable = KCS_FABAssetInsIndexTable::find(this.KCS_FABAssetIndexIdInsurance, year(this.InsuranceDate1));
    insIndexTableActual = KCS_FABAssetInsIndexTable::find(this.KCS_FABAssetIndexIdInsurance, year(DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone())));

    if (!insIndexTableActual)
    {
        warning(strfmt("@FAB107", year(DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()))));
        return this.InsuredValue;
    }

    if (!insIndexTable)
    {
        warning(strfmt("@FAB107",year(this.InsuranceDate1)));
        return this.InsuredValue;
    }

    return CurrencyExchangeHelper::amount((this.KCS_FABAcquisitionPrice * insIndexTableActual.insIndex) / insIndexTable.insIndex);
}
